#!/usr/bin/env bash
set -euo pipefail

LIB=/usr/local/lib/apitoken-watchdog/watchdog-lib.sh
[[ -r $LIB ]] || { printf 'watchdog library is not installed\n' >&2; exit 1; }
# shellcheck source=deploy/watchdog-lib.sh
source "$LIB"

STATE_ROOT=/var/lib/apitoken/watchdog
ENGINE_RELEASE_ROOT=/srv/claude-api/releases
ENGINE_DATA_ROOT=/srv/claude-api/data
PRODUCER_SHA=d69868fb700aaeb9b6723d8780bb29be4aab9c0d
EVIDENCE_PARENT=$STATE_ROOT/gpt-image-2-surface-probe
MEDIUM_BUDGET_NANOUSD=180460000
HIGH_BUDGET_NANOUSD=714130000
MULTI_REF_BUDGET_NANOUSD=128022330000

# Two static 1024x1024 solid-color PNG references (valid under the GPT Image 2 size constraints).
# They let the multi-reference edit probe run without consuming a paid generation first.
GPT_IMAGE_2_PROBE_REF_BLUE_
GPT_IMAGE_2_PROBE_REF_RED_
readonly GPT_IMAGE_2_PROBE_REF_BLUE_B64 GPT_IMAGE_2_PROBE_REF_RED_B64

[[ $# -eq 1 ]] || wd_die "usage: gpt-image-2-surface-probe-gate.sh <exact-producer-sha>"
SHA=$1
wd_validate_sha "$SHA"
[[ $SHA == "$PRODUCER_SHA" ]] \
  || wd_die "GPT Image 2 surface probe is pinned to producer $PRODUCER_SHA"
[[ $(id -u) == 0 ]] || wd_die "GPT Image 2 surface probe must run through the fixed root bridge"
command -v jq >/dev/null || wd_die "jq is required for GPT Image 2 surface probe evidence"
command -v sha256sum >/dev/null || wd_die "sha256sum is required for GPT Image 2 surface probe evidence"
command -v base64 >/dev/null || wd_die "base64 is required for GPT Image 2 surface probe references"

release=$ENGINE_RELEASE_ROOT/$SHA
current=$(readlink -f -- "$ENGINE_RELEASE_ROOT/current")
[[ $current == "$release" ]] || wd_die "GPT Image 2 surface probe requires current engine release $SHA"
binary=$release/claude-api
[[ -f $binary && ! -L $binary && -x $binary ]] \
  || wd_die "exact GPT Image 2 surface probe binary is missing"

[[ ! -L $EVIDENCE_PARENT ]] || wd_die "GPT Image 2 surface probe evidence parent must not be a symlink"
install -d -o deploy -g deploy -m 0700 -- "$EVIDENCE_PARENT"
root=$EVIDENCE_PARENT/$SHA
install -d -o deploy -g deploy -m 0700 -- "$root"

# Two static 1024x1024 PNG references (solid blue/red), valid under the GPT Image 2 size
# constraints. They let the multi-reference edit probe run without consuming a paid generation.
write_reference() {
  local path=$1 payload=$2
  install -o deploy -g deploy -m 0600 /dev/null "$path"
  base64 -d <<<"$payload" >"$path"
  [[ $(stat -c '%s' -- "$path") -gt 100 ]] || wd_die "GPT Image 2 surface probe reference is empty"
  [[ $(od -An -tx1 -N8 -- "$path" | tr -d ' \n') == 89504e470d0a1a0a ]] \
    || wd_die "GPT Image 2 surface probe reference is not a PNG"
}

write_prompt() {
  local path=$1 text=$2
  install -o deploy -g deploy -m 0600 /dev/null "$path"
  printf '%s\n' "$text" >"$path"
}

# A probe is GREEN-informative when the wire honored the requested control (exact checkpoint),
# normalized it (sanitized controls-mismatch journal with the returned controls), or cleanly
# rejected it before dispatch. outcome_unknown stays fatal: a paid operation may have run without
# evidence, so the delivery must call attention instead of reporting a verdict.
probe_verdict() {
  local probe=$1 quality=$2 budget=$3 checkpoint=$root/$1/probe.json
  local journal=$root/$1/.probe.json.openai-image-canary-run/journal.json
  local state returned_quality output_tokens image_input_tokens
  if [[ -f $checkpoint ]]; then
    jq -e --arg sha "$SHA" --argjson budget "$budget" --arg quality "$quality" '
      .schema_version == 1 and
      .model == "gpt-image-2" and
      (.operation == "generation" or .operation == "edit") and
      (.profile | type == "string" and length > 0) and
      (.image_turn_id | type == "string" and length > 0) and
      .provider.quality == $quality and
      .provider.background == "opaque" and
      (.usage.output_tokens | type == "number" and . > 0 and floor == .) and
      .implementation_sha == $sha and
      .authorization_budget_nanousd == $budget and
      (.output_sha256 | type == "string" and test("^sha256:[0-9a-f]{64}$"))
    ' "$checkpoint" >/dev/null \
      || wd_die "GPT Image 2 surface probe $probe checkpoint is not exact valid evidence"
    returned_quality=$(jq -r '.provider.quality' "$checkpoint")
    output_tokens=$(jq -r '.usage.output_tokens // 0' "$checkpoint")
    image_input_tokens=$(jq -r '.usage.input_tokens_details.image_tokens // 0' "$checkpoint")
    jq -nc --arg v honored --arg rq "$returned_quality" \
      --argjson ot "$output_tokens" --argjson iit "$image_input_tokens" \
      '{verdict:$v,returned_quality:$rq,output_tokens:$ot,image_input_tokens:$iit}'
    return 0
  fi
  [[ -f $journal ]] || wd_die "GPT Image 2 surface probe $probe left no terminal evidence"
  jq -e --arg sha "$SHA" --argjson budget "$budget" '
    .schema_version == 1 and
    .model == "gpt-image-2" and
    (.profile | type == "string" and length > 0) and
    (.image_turn_id | type == "string" and length > 0) and
    .implementation_sha == $sha and
    .authorization_budget_nanousd == $budget
  ' "$journal" >/dev/null \
    || wd_die "GPT Image 2 surface probe $probe journal is not exact valid evidence"
  state=$(jq -r '.state' "$journal")
  case "$state" in
    rejected)
      jq -nc '{verdict:"rejected",returned_quality:null,output_tokens:0,image_input_tokens:0}'
      ;;
    evidence_controls_mismatch)
      returned_quality=$(jq -r '.returned.provider.quality' "$journal")
      output_tokens=$(jq -r '.returned.usage.output_tokens // 0' "$journal")
      image_input_tokens=$(jq -r '.returned.usage.input_tokens_details.image_tokens // 0' "$journal")
      jq -nc --arg v normalized --arg rq "$returned_quality" \
        --argjson ot "$output_tokens" --argjson iit "$image_input_tokens" \
        '{verdict:$v,returned_quality:$rq,output_tokens:$ot,image_input_tokens:$iit}'
      ;;
    *)
      wd_die "GPT Image 2 surface probe $probe ended in non-informative state $state"
      ;;
  esac
}

run_probe() {
  local probe=$1 quality=$2 budget=$3 references=$4
  local dir=$root/$probe prompt=$root/$probe/prompt.txt
  local output=$root/$probe/probe.png checkpoint=$root/$probe/probe.json
  if [[ -e $output || -L $output || -e $checkpoint || -L $checkpoint \
      || -e $root/$probe/.probe.json.openai-image-canary-run ]]; then
    return 0
  fi
  install -d -o deploy -g deploy -m 0700 -- "$dir"
  if [[ $references == 0 ]]; then
    write_prompt "$prompt" \
      'A simple flat illustration of a ceramic mug on a plain beige background. No text, logos, people, brands, or copyrighted characters.'
  else
    write_prompt "$prompt" \
      'Combine the two supplied reference images side by side into one simple flat illustration on a plain beige background. Add no text, logos, people, brands, or copyrighted characters.'
  fi

  local args=(openai-image-canary
    --prompt-file "$prompt"
    --output "$output"
    --checkpoint "$checkpoint"
    --budget-nanousd "$budget"
    --quality "$quality")
  if [[ $references == 2 ]]; then
    args+=(--reference "$root/multi-ref/ref-blue.png" --reference "$root/multi-ref/ref-red.png")
  fi
  args+=(--execute)

  local deploy_uid deploy_gid
  deploy_uid=$(id -u deploy)
  deploy_gid=$(id -g deploy)
  HOME=/home/deploy timeout --signal=TERM --kill-after=30s 900s \
    setpriv --reuid="$deploy_uid" --regid="$deploy_gid" --init-groups --no-new-privs \
    "$binary" "${args[@]}" >/dev/null 2>&1 || true
}

load_openai_runtime_environment() {
  local unit pid executable entry name provider
  local entries=()
  for unit in claude-api-openai@8793.service claude-api-openai@8797.service; do
    [[ $(systemctl show "$unit" -p ActiveState --value 2>/dev/null) == active ]] || continue
    pid=$(systemctl show "$unit" -p MainPID --value 2>/dev/null)
    [[ $pid =~ ^[1-9][0-9]*$ ]] || continue
    executable=$(readlink -f -- "/proc/$pid/exe" 2>/dev/null) || continue
    [[ $executable == "$binary" ]] || continue

    entries=()
    provider=
    while IFS= read -r -d '' entry; do
      [[ $entry == *=* ]] || wd_die "running OpenAI slot contains an invalid environment entry"
      name=${entry%%=*}
      [[ $name =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] \
        || wd_die "running OpenAI slot contains an invalid environment name"
      case "$name" in
        CLAUDE_API_PROVIDER) provider=${entry#*=}; entries+=("$entry") ;;
        CLAUDE_API_DATABASE_URL|CLAUDE_API_AFFINITY_SECRET|CLAUDE_API_REDIS_URL|\
          CLAUDE_API_AFFINITY_REDIS_URL|CLAUDE_API_CODEX_*) entries+=("$entry") ;;
      esac
    done <"/proc/$pid/environ"
    [[ $provider == openai ]] || continue

    for entry in "${entries[@]}"; do
      export "$entry"
    done
    return 0
  done
  wd_die "no active exact-release OpenAI slot can supply the parsed production environment"
}

# Production EnvironmentFile values are systemd syntax, not shell syntax. Reuse the exact active
# OpenAI slot's already parsed environment instead of evaluating root-only files as Bash. Values stay
# in process environments (never argv or logs), and fixed canary overrides are applied afterwards.
load_openai_runtime_environment
export HOME=/home/deploy
export SUB_CFG_DIR=$ENGINE_DATA_ROOT
export CLAUDE_API_PROVIDER=openai
export CLAUDE_API_CLAUDESTORE_FALLBACK_ENABLED=0
export CLAUDE_API_CLAUDESTORE_CODEX_FALLBACK_ENABLED=0

umask 077
install -d -o deploy -g deploy -m 0700 -- "$root/multi-ref"
write_reference "$root/multi-ref/ref-blue.png" "$GPT_IMAGE_2_PROBE_REF_BLUE_B64"
write_reference "$root/multi-ref/ref-red.png" "$GPT_IMAGE_2_PROBE_REF_RED_B64"

run_probe medium medium "$MEDIUM_BUDGET_NANOUSD" 0
run_probe high high "$HIGH_BUDGET_NANOUSD" 0
run_probe multi-ref low "$MULTI_REF_BUDGET_NANOUSD" 2

medium_verdict=$(probe_verdict medium medium "$MEDIUM_BUDGET_NANOUSD")
high_verdict=$(probe_verdict high high "$HIGH_BUDGET_NANOUSD")
multi_ref_verdict=$(probe_verdict multi-ref low "$MULTI_REF_BUDGET_NANOUSD")

jq -nc --argjson medium "$medium_verdict" --argjson high "$high_verdict" \
  --argjson multi_ref "$multi_ref_verdict" \
  '{medium:$medium,high:$high,multi_ref:$multi_ref}'
